#!/usr/bin/env dotnet
// Find the earliest Friday the 13th in the proleptic Gregorian calendar (starting 0001-01-01)
// and count all Friday the 13ths in a full 400-year cycle.

// The Gregorian calendar repeats every 400 years (146097 days = exactly 20871 weeks).
// .NET's DateTime uses the proleptic Gregorian calendar starting at 0001-01-01.

// Find the earliest Friday the 13th
DateTime earliest = DateTime.MinValue; // 0001-01-01
for (int year = 1; year <= 1; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = d;
            goto found;
        }
    }
}
found:
Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest.DayOfWeek})");

// Count Friday the 13ths in a full 400-year cycle (years 1–400)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}
Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// Bonus: which day-of-week is the 13th most likely to fall on?
var dayCounts = new int[7];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        dayCounts[(int)d.DayOfWeek]++;
    }
}

Console.WriteLine("\n13th falls on each day (400-year cycle):");
for (int i = 0; i < 7; i++)
    Console.WriteLine($"  {(DayOfWeek)i,-10}: {dayCounts[i]}");
EOF
